namespace Quantum.MultiQubit {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Diagnostics;

    // Bell state creation with CNOT
    operation CreateBellState() : (Result, Result) {
        use (control, target) = (Qubit(), Qubit());

        // Put control in superposition
        H(control);

        // Apply CNOT
        CNOT(control, target);

        // Now in Bell state |Φ⁺⟩
        DumpMachine();

        let result1 = M(control);
        let result2 = M(target);

        return (result1, result2);
    }

    // Toffoli gate demonstration
    operation ToffoliDemo() : (Result, Result, Result) {
        use (a, b, c) = (Qubit(), Qubit(), Qubit());

        // Set up |110⟩
        X(a);
        X(b);

        // Apply Toffoli (CCNOT)
        CCNOT(a, b, c);

        // Now in |111⟩
        let resultA = M(a);
        let resultB = M(b);
        let resultC = M(c);

        return (resultA, resultB, resultC);
    }

    @EntryPoint()
    operation Main() : Unit {
        Message("Creating Bell state...");
        let (r1, r2) = CreateBellState();
        Message($"Bell measurement: ({r1}, {r2}) - always correlated!");
    }
}
